        className: "language-php",
        children: "<?php\n\nnamespace App\\Models\\Finance;\n\nuse App\\Models\\User;\nuse Illuminate\\Database\\Eloquent\\Model;\nuse Illuminate\\Database\\Eloquent\\Relations\\BelongsTo;\nuse Illuminate\\Database\\Eloquent\\Relations\\HasMany;\n\nclass KycVerification extends Model\n{\n    protected $table = 'finance_kyc_verifications';\n\n    protected $fillable = [\n        'user_id',\n        'status',\n        'risk_profile',\n        'risk_score',\n        'verification_data',\n        'completed_at',\n    ];\n\n    protected $casts = [\n        'verification_data' => 'array',\n        'completed_at' => 'datetime',\n    ];\n\n    public function customer(): BelongsTo\n    {\n        return $this->belongsTo(User::class, 'user_id');\n    }\n\n    public function documents(): HasMany\n    {\n        return $this->hasMany(KycDocument::class, 'verification_id');\n    }\n}\n\nclass KycDocument extends Model\n{\n    protected $table = 'finance_kyc_documents';\n\n    protected $fillable = [\n        'verification_id',\n        'document_type',\n        'file_path',\n        'file_size',\n        'issuing_country',\n        'expiry_date',\n        'face_confidence',\n        'status',\n    ];\n\n    protected $casts = [\n        'expiry_date' => 'date',\n        'face_confidence' => 'float',\n    ];\n\n    public function verification(): BelongsTo\n    {\n        return $this->belongsTo(KycVerification::class, 'verification_id');\n    }\n}\n\nclass WatchlistEntry extends Model\n{\n    protected $table = 'finance_watchlist_entries';\n\n    protected $fillable = [\n        'list_name',\n        'full_name',\n        'aliases',\n        'country',\n        'date_of_birth',\n        'category',\n        'details',\n        'is_active',\n        'source',\n    ];\n\n    protected $casts = [\n        'aliases' => 'array',\n        'details' => 'array',\n        'date_of_birth' => 'date',\n        'is_active' => 'boolean',\n    ];\n\n    public function scopeActive($query)\n    {\n        return $query->where('is_active', true);\n    }\n}\n"
